SELECT m.id,m.event_key,'EVENT_OR_ACK_MISSING' AS discrepancy FROM messages m WHERE m.status='PROCESSED' AND ((SELECT COUNT(*) FROM business_events b WHERE b.message_id=m.id)<>1 OR (SELECT COUNT(*) FROM outbox o WHERE o.message_id=m.id)<>1) UNION ALL SELECT m.id,m.event_key,'UNPROCESSED_HAS_BUSINESS_EFFECT' FROM messages m WHERE m.status<>'PROCESSED' AND EXISTS (SELECT 1 FROM business_events b WHERE b.message_id=m.id);
